
const ITEMS = {"fail_00001.jpg": {"img": "", "prev": "ZAD", "note": "上次提交(被拒): ZAD"}, "fail_00002.jpg": {"img": "", "prev": "HIT", "note": "上次提交(被拒): HIT"}, "fail_00003.jpg": {"img": "", "prev": "M6EZ", "note": "上次提交(被拒): M6EZ"}, "fail_00004.jpg": {"img": "", "prev": "BXD6", "note": "上次提交(被拒): BXD6"}, "fail_00005.jpg": {"img": "", "prev": "JWN", "note": "上次提交(被拒): JWN"}, "fail_00006.jpg": {"img": "", "prev": "5UT", "note": "上次提交(被拒): 5UT"}, "fail_00007.jpg": {"img": "", "prev": "MBYF", "note": "上次提交(被拒): MBYF"}, "fail_00008.jpg": {"img": "", "prev": "T7M", "note": "上次提交(被拒): T7M"}, "fail_00009.jpg": {"img": "", "prev": "R7M", "note": "上次提交(被拒): R7M"}, "fail_00010.jpg": {"img": "", "prev": "WL0P", "note": "上次提交(被拒): WL0P"}, "fail_00011.jpg": {"img": "", "prev": "M9I1B", "note": "上次提交(被拒): M9I1B"}, "fail_00012.jpg": {"img": "", "prev": "6YT", "note": "上次提交(被拒): 6YT"}, "fail_00013.jpg": {"img": "", "prev": "7WI", "note": "上次提交(被拒): 7WI"}, "fail_00014.jpg": {"img": "", "prev": "7GPWN", "note": "上次提交(被拒): 7GPWN"}, "fail_00015.jpg": {"img": "", "prev": "R1W", "note": "上次提交(被拒): R1W"}, "fail_00016.jpg": {"img": "", "prev": "JH9", "note": "上次提交(被拒): JH9"}, "fail_00017.jpg": {"img": "", "prev": "9E4", "note": "上次提交(被拒): 9E4"}, "fail_00018.jpg": {"img": "", "prev": "W20", "note": "上次提交(被拒): W20"}, "fail_00019.jpg": {"img": "", "prev": "OW8E", "note": "上次提交(被拒): OW8E"}, "fail_00020.jpg": {"img": "", "prev": "8WK5", "note": "上次提交(被拒): 8WK5"}, "fail_00021.jpg": {"img": "", "prev": "TOVV", "note": "上次提交(被拒): TOVV"}, "fail_00022.jpg": {"img": "", "prev": "5WW", "note": "上次提交(被拒): 5WW"}, "Hfail_00001.jpg": {"img": "", "prev": "", "note": "上次提交=测试码(无效)"}, "Hfail_00002.jpg": {"img": "", "prev": "", "note": "上次提交=测试码(无效)"}, "Hfail_00003.jpg": {"img": "", "prev": "r0w3", "note": "上次提交(被拒): r0w3"}, "Hfail_00004.jpg": {"img": "", "prev": "1r21", "note": "上次提交(被拒): 1r21"}, "Hfail_00005.jpg": {"img": "", "prev": "1zrz", "note": "上次提交(被拒): 1zrz"}};
const names = Object.keys(ITEMS);
const STORE = "portal_relabel_rejected_v1";
let labels = {}, idx = 0;
try { labels = JSON.parse(localStorage.getItem(STORE) || "{}"); } catch(e) {}
function save(){ localStorage.setItem(STORE, JSON.stringify(labels));
  localStorage.setItem(STORE+"_idx", String(idx)); }
function render(){ const n = names[idx], it = ITEMS[n];
  document.getElementById("img").src = "data:image/jpeg;base64," + it.img;
  document.getElementById("p").textContent = `第 ${idx+1} / ${names.length} 张`;
  document.getElementById("prev").textContent = it.note;
  const c = document.getElementById("input");
  c.value = labels[n] !== undefined ? labels[n] : it.prev;
  c.focus(); c.select(); }
document.getElementById("input").addEventListener("keydown", e => {
  if (e.key === "Enter") { e.preventDefault();
    const n = names[idx], v = document.getElementById("input").value.trim().toUpperCase();
    if (v) labels[n] = v; else delete labels[n];
    save(); idx = Math.min(idx + 1, names.length - 1); render(); }
  if (e.key === "ArrowLeft") { idx = Math.max(idx - 1, 0); render(); }});
document.getElementById("export").onclick = () => {
  const text = names.filter(n => labels[n]).map(n => `${n} ${labels[n]}`).join("
") + "
";
  const a = document.createElement("a");
  a.href = URL.createObjectURL(new Blob([text], {type: "text/plain"}));
  a.download = "relabel_rejected.txt"; a.click(); };
render();
